/**
 * Production sky asset loading (M7): the KTX2 cubemaps and bright-star
 * catalog generated by tools/generateSkyAssets.ts. Format contracts (grid
 * dimensions, record layout, radiometric units) are documented there and in
 * assets/sky/bright-stars.json; this module validates them on load so a
 * stale asset set fails loudly instead of rendering a subtly wrong sky.
 */
import { read as readKtx, VK_FORMAT_R16G16B16A16_SFLOAT } from 'ktx-parse';
import type { SkyAssetData } from './tracePass';

/** Mirrors SKY_GRID_NTH × SKY_GRID_NPH in sky.wgsl / tools/generateSkyAssets.ts. */
const GRID_CELLS = 32 * 64;
const STAR_STRIDE = 8;

export interface SkyAttribution {
  panorama: string;
  catalog: string;
}

interface StarsMeta {
  starCount: number;
  gridNth: number;
  gridNph: number;
  sources: SkyAttribution;
}

function parseCubemapKtx2(bytes: Uint8Array, label: string): { faceSize: number; texels: Uint8Array } {
  const container = readKtx(bytes);
  if (container.vkFormat !== VK_FORMAT_R16G16B16A16_SFLOAT || container.faceCount !== 6) {
    throw new Error(`${label}: expected an uncompressed rgba16f cubemap KTX2`);
  }
  const level = container.levels[0];
  if (!level) throw new Error(`${label}: KTX2 has no level data`);
  const faceSize = container.pixelWidth;
  if (level.levelData.byteLength !== faceSize * faceSize * 8 * 6) {
    throw new Error(`${label}: level size does not match ${faceSize}²×6 rgba16f`);
  }
  return { faceSize, texels: level.levelData };
}

export async function loadSkyAssets(): Promise<{ data: SkyAssetData; attribution: SkyAttribution }> {
  const fetchBytes = async (url: URL): Promise<Uint8Array> => {
    const res = await fetch(url);
    if (!res.ok) throw new Error(`sky asset fetch failed: ${url}`);
    return new Uint8Array(await res.arrayBuffer());
  };
  const [skyBytes, aggBytes, starBytes, metaRes] = await Promise.all([
    fetchBytes(new URL('../../assets/sky/sky-cubemap.ktx2', import.meta.url)),
    fetchBytes(new URL('../../assets/sky/star-agg.ktx2', import.meta.url)),
    fetchBytes(new URL('../../assets/sky/bright-stars.bin', import.meta.url)),
    fetch(new URL('../../assets/sky/bright-stars.json', import.meta.url)),
  ]);
  if (!metaRes.ok) throw new Error('sky asset fetch failed: bright-stars.json');
  const meta = (await metaRes.json()) as StarsMeta;
  if (meta.gridNth * meta.gridNph !== GRID_CELLS) {
    throw new Error('sky assets: star grid dimensions do not match the shader (regenerate assets/sky)');
  }
  const sky = parseCubemapKtx2(skyBytes, 'sky-cubemap.ktx2');
  const agg = parseCubemapKtx2(aggBytes, 'star-agg.ktx2');

  const recordBytes = meta.starCount * STAR_STRIDE * 4;
  const cellBytes = (GRID_CELLS + 1) * 4;
  if (starBytes.byteLength !== recordBytes + cellBytes) {
    throw new Error('sky assets: bright-stars.bin size does not match its metadata');
  }
  const buf = new ArrayBuffer(starBytes.byteLength);
  new Uint8Array(buf).set(starBytes);
  const starRecords = new Float32Array(buf, 0, meta.starCount * STAR_STRIDE);
  const cellStart = new Uint32Array(buf, recordBytes, GRID_CELLS + 1);
  if (cellStart[GRID_CELLS] !== meta.starCount) {
    throw new Error('sky assets: CSR cell offsets are inconsistent with the star count');
  }
  return {
    data: {
      faceSize: sky.faceSize,
      cubemap: sky.texels,
      aggFaceSize: agg.faceSize,
      aggCubemap: agg.texels,
      starRecords,
      cellStart,
    },
    attribution: meta.sources,
  };
}
